package main
import("testing";"os";"encoding/binary";"fmt";"encoding/json")
func TestLocalSkillFieldProbe(t *testing.T){path:=os.Getenv("MABI_SKILL_PCAP");if path==""{t.Skip("local")};f,e:=os.Open(path);if e!=nil{t.Fatal(e)};defer f.Close();type skill struct{p []byte;name string;n int};recent:=map[uint64][]skill{};matches:=map[string]int{};values:=map[string]map[uint64]bool{};shapes:=map[string]int{};_,e=replayPCAPObserved(f,16000,func(id uint32,p []byte,out bool){if out{return};if id==0x1d4f8{if s,ok:=decodeJPSkill(p);ok{n:=int(binary.LittleEndian.Uint32(p[8:]));recent[s.Actor]=append(recent[s.Actor],skill{append([]byte(nil),p...),s.Code,12+n});if len(recent[s.Actor])>8{recent[s.Actor]=recent[s.Actor][1:]};shapes[fmt.Sprintf("%s/tail%d",s.Class,len(p)-12-n)]++}};if id!=0x5243||len(p)!=53{return};actor:=binary.LittleEndian.Uint64(p);for _,s:=range recent[actor]{for doff:=20;doff+4<=len(p);doff++{v:=uint64(binary.LittleEndian.Uint32(p[doff:]));if v<2||v==actor||v==binary.LittleEndian.Uint64(p[8:]){continue};for soff:=s.n;soff+4<=len(s.p);soff++{if uint64(binary.LittleEndian.Uint32(s.p[soff:]))==v{key:=fmt.Sprintf("damage+%d/skillTail+%d",doff,soff-s.n);matches[key]++;if values[key]==nil{values[key]=map[uint64]bool{}};values[key][v]=true}}}}});if e!=nil{t.Fatal(e)};distinct:=map[string]int{};for k,v:=range values{distinct[k]=len(v)};data,_:=json.MarshalIndent(map[string]any{"matches":matches,"distinctValues":distinct,"skillTailShapes":shapes},"","  ");if out:=os.Getenv("MABI_SKILL_REPORT");out!=""{_=os.WriteFile(out,data,0600)}}
